import * as THREE from 'three/webgpu';
import { texture, uniform, mul, add, sub, vec3 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.copy(config.position || new THREE.Vector3(0, 0, 0));

  const WIDTH = 4.0;
  const HEIGHT = 2.5;

  // Load textures
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  imageTexture.colorSpace = THREE.SRGBColorSpace;
  depthTexture.colorSpace = THREE.NoColorSpace;

  // Create tessellated geometry for displacement
  const geometry = new THREE.PlaneGeometry(WIDTH, HEIGHT, 64, 64);

  // TSL shader nodes
  const colorMap = texture(imageTexture);
  const depthMap = texture(depthTexture);
  const displacementScale = uniform(0.18);

  // Displacement: (depth - 0.5) * scale applied to Z axis
  const displacement = mul(
    sub(depthMap, 0.5),
    displacementScale
  );

  // Material with color and displacement
  const material = new THREE.MeshPhongNodeMaterial({
    colorNode: colorMap,
    transparent: true,
    side: THREE.DoubleSide,
    opacity: 0,
  });

  // Apply vertex displacement via positionNode
  const positionOffset = mul(displacement, vec3(0, 0, 1));
  material.positionNode = add(
    new THREE.PositionNode(),
    positionOffset
  );

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Scrim gradient overlay at bottom (0b0b1000 to 0b0b10eb)
  const scrimGeometry = new THREE.PlaneGeometry(WIDTH, HEIGHT * 0.65);
  const scrimMaterial = new THREE.MeshBasicMaterial({
    color: 0x0b0b10,
    transparent: true,
    opacity: 0.92,
    side: THREE.DoubleSide,
  });
  const scrim = new THREE.Mesh(scrimGeometry, scrimMaterial);
  scrim.position.set(0, -HEIGHT * 0.175, 0.002);
  group.add(scrim);

  // Caption block: anchored bottom-left with 0.5 unit padding
  const captionGroup = new THREE.Group();
  captionGroup.position.set(-WIDTH / 2 + 0.5, -HEIGHT / 2 + 0.5, 0.01);

  // Kicker (NOVA ATELIER / GENEVA, 9px 700)
  const kicker = ctx.fontAtlas.createText('NOVA ATELIER / GENEVA', {
    fontSize: 0.09,
    fontWeight: 700,
  });
  kicker.position.y = 0;
  captionGroup.add(kicker);

  // Headline (Time, Machined., 34px 600)
  const headline = ctx.fontAtlas.createText('Time, Machined.', {
    fontSize: 0.34,
    fontWeight: 600,
  });
  headline.position.y = -0.25;
  captionGroup.add(headline);

  // Accent hairline bar: 0.75w x 0.02h, #ff2a38 emissive 1.8
  const accentGeometry = new THREE.PlaneGeometry(0.75, 0.02);
  const accentMaterial = new THREE.MeshBasicMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
    toneMapped: false,
  });
  const accentBar = new THREE.Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(0.375, -0.35, 0);
  captionGroup.add(accentBar);

  // Body (Every case begins..., 13px 400)
  const body = ctx.fontAtlas.createText('Every case begins as a single billet of 904L steel.', {
    fontSize: 0.13,
    fontWeight: 400,
  });
  body.position.y = -0.5;
  captionGroup.add(body);

  // Caption (CALIBRE NA-01 / 72 HOUR RESERVE, 9px 400)
  const caption = ctx.fontAtlas.createText('CALIBRE NA-01 / 72 HOUR RESERVE', {
    fontSize: 0.09,
    fontWeight: 400,
  });
  caption.position.y = -0.75;
  captionGroup.add(caption);

  // Initial state: offset up and transparent for animation
  captionGroup.position.y += 0.4;
  captionGroup.opacity = 0;

  group.add(captionGroup);

  // Animation timeline
  const timeline = gsap.timeline();

  // Plate mount fade-in: 500ms, cubic-bezier(0.25,0.46,0.45,0.94)
  timeline.to(material, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  }, 0);

  // Caption block rise-in: 700ms starting at 120ms, cubic-bezier(0.215,0.61,0.355,1)
  timeline.to(captionGroup.position, {
    y: -HEIGHT / 2 + 0.5,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
  }, 0.12);

  timeline.to(captionGroup, {
    opacity: 1,
    duration: 0.7,
    ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)',
  }, 0.12);

  // Apply parallax-scroll cinematic primitive
  if (ctx.primitives?.['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](mesh, { intensity: 0.35 });
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    geometry.dispose();
    scrimGeometry.dispose();
    accentGeometry.dispose();

    material.dispose();
    scrimMaterial.dispose();
    accentMaterial.dispose();

    imageTexture.dispose();
    depthTexture.dispose();

    timeline.kill();
    gsap.killTweensOf([material, captionGroup.position, captionGroup]);
  };

  return group;
}
